8	class AcceptanceTest extends AcceptanceBase {
9	
10		@Test
11		void corePhoneWhenNoEmail() throws Exception {
12			int id = createOwnerOk(ownerNode());
13			getOwner(id).andExpect(jsonPath("$.contactPreference").value("PHONE"));
14		}
15	
16		@Test
17		void functionalityEmailWhenPresent() throws Exception {
18			ObjectNode o = ownerNode();
19			o.put("email", uniqueEmail());
20			int id = createOwnerOk(o);
21			getOwner(id).andExpect(jsonPath("$.contactPreference").value("EMAIL"));
22		}
23	}
